-- Schelet LOCAL (PGlite) pentru 20270115b (Izometrie: citirile NDT pe server + amprenta pachetului). NU se rulează pe nicio bază reală.
-- Se încarcă DUPĂ supabase/tests/20270114a_izometrie_buletine_ndt_schelet.sql și ÎNAINTEA aplicării migrării 20270114a (proba o aplică ca
-- runnerul), ca baza să fie „producția de după 20270114a”. Adaugă DOAR ce citește în plus 20270115b:
--   executie_pachete_lansare: updated_at, km_start_m, revizie, cod_document_full (coloanele citite de amprentaPachet din src/lib/izoExportIzo.js);
--   executie_tevi: id, pachet_id + cele 15 câmpuri din CAMPURI_RAND_AMPRENTA (tipurile de pe producție NU sunt citite aici: migrarea cere doar
--   existența coloanelor, iar amprenta le ia prin jsonb, oricare ar fi tipul — limită declarată în raport), cu RLS de citire ca pachetele.
ALTER TABLE public.executie_pachete_lansare ADD COLUMN updated_at timestamptz DEFAULT now(), ADD COLUMN km_start_m numeric,
  ADD COLUMN revizie integer, ADD COLUMN cod_document_full text;
CREATE TABLE public.executie_tevi (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, pachet_id bigint REFERENCES public.executie_pachete_lansare(id),
  poz_in_pachet integer, tip_rand text, serie_unica text, sudura_cod text, sudura_refacuta boolean DEFAULT false, lungime_m numeric, tip text,
  dimensiune text, sarja text, unghi_curba numeric, lot text, observatii text, pm_cod text, pa_ut_cod text, ut_cod text);
ALTER TABLE public.executie_tevi ENABLE ROW LEVEL SECURITY;
CREATE POLICY executie_tevi_select ON public.executie_tevi FOR SELECT TO authenticated USING ((SELECT public.fn_executie_pachete_acces(false)));
REVOKE ALL ON public.executie_tevi FROM anon;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.executie_tevi FROM authenticated;
